<script lang="ts">
  import { ZONES } from '$lib/domain/catalog';
  import { gameSession } from '$lib/stores/gameStore';
  import type { GameState, Mission } from '$lib/domain/types';
  let { game } = $props<{ game: GameState }>();
  function accept(mission: Mission): void { gameSession.updateGame((state) => ({ ...state, missions: state.missions.map((item) => item.id === mission.id ? { ...item, status: 'active' as const } : item) }), true); }
</script>
<section class="management-screen"><header class="management-header"><div><span class="eyebrow">CAPTAIN'S LEDGER</span><h1>임무와 소문</h1><p class="muted">고정된 전설과 매일 바뀌는 항구의 기회를 함께 추적합니다.</p></div><span class="tag">활성 {game.missions.filter((item) => item.status === 'active').length}</span></header><div class="management-grid"><article class="panel span-8"><div class="panel-title"><div><span class="eyebrow">CONTRACTS</span><h2>계약서</h2></div></div><div class="list-stack">{#each game.missions as mission}<div class="list-row" style="grid-template-columns:1fr auto"><div><span class="eyebrow">{mission.story ? 'STORY' : mission.type} · {ZONES[mission.zoneId].name}</span><h3 style="margin:.25rem 0">{mission.title}</h3><p class="muted" style="font-size:.74rem;margin:0">{mission.description}</p><div class="meter" style="margin-top:.6rem"><span style={`--value:${mission.progress / mission.goal * 100}%`}></span></div></div><div style="text-align:right"><span class={`tag ${mission.status === 'complete' ? 'success' : ''}`}>{mission.status}</span><div class="costs" style="justify-content:flex-end;margin:.5rem 0"><span class="cost">명성 +{mission.renownReward}</span>{#each Object.entries(mission.reward) as [id, amount]}<span class="cost">{id} {amount}</span>{/each}</div>{#if mission.status === 'available'}<button class="btn small" onclick={() => accept(mission)}>수락</button>{/if}</div></div>{/each}</div></article><article class="panel span-4"><span class="eyebrow">RUMORS</span><h2>오늘의 소문</h2>{#each game.world.recentEvents as event}<p class="muted" style="padding:.7rem;border-left:2px solid var(--brass);background:rgba(0,0,0,.16)">{event}</p>{/each}<p class="faint">정보상 거점을 업그레이드하면 목표 방어력과 희귀 항로가 공개됩니다.</p></article></div></section>
